import{A as e,H as t,P as n,_ as r,a as i,f as a,g as o,h as s,l as c,t as l,u}from"./chunks/plugin-vue_export-helper.I53torQa.js";var d=JSON.parse(`{"title":"大模型推理优化技术概览","description":"大模型推理优化技术知识地图：推理引擎、优化方向、关键技术（KV Cache、并行、量化、解码、调度）、性能指标与新兴趋势一览。","frontmatter":{"title":"大模型推理优化技术概览","description":"大模型推理优化技术知识地图：推理引擎、优化方向、关键技术（KV Cache、并行、量化、解码、调度）、性能指标与新兴趋势一览。"},"headers":[],"relativePath":"inference/foundations/llm-inference-infra.md","filePath":"inference/foundations/llm-inference-infra.md","lastUpdated":1787713844000}`),f={name:`inference/foundations/llm-inference-infra.md`};function p(l,d,f,p,m,h){let g=n(`Mermaid`);return e(),a(`div`,null,[d[2]||=c(`h1`,{id:`大模型推理优化技术概览`,tabindex:`-1`},[o(`大模型推理优化技术概览 `),c(`a`,{class:`header-anchor`,href:`#大模型推理优化技术概览`,"aria-label":`Permalink to “大模型推理优化技术概览”`},`​`)],-1),d[3]||=c(`blockquote`,null,[c(`p`,null,[o(`推理优化的本质：`),c(`strong`,null,`用内存换时间、用带宽换算力、用并行换吞吐`),o(`。从资源瓶颈看，最终落到 5 个维度——计算（算子）、内存（KV Cache）、带宽（并行/通信）、调度（批处理/分离）、模型（量化/解码）；从工程手段看，可归纳为 5 个方向（见第 2 节）。以下按「引擎 → 方向 → 技术 → 分层要点 → 指标 → 趋势」展开。`)])],-1),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-8`,class:`mermaid`,graph:`graph%20TB%0A%20%20Root%5B%22%E5%A4%A7%E6%A8%A1%E5%9E%8B%E6%8E%A8%E7%90%86%E4%BC%98%E5%8C%96%22%5D%20--%3E%20Eng%5B%22%E5%BC%95%E6%93%8E%E5%B1%82%3Cbr%2F%3EvLLM%20%C2%B7%20SGLang%20%C2%B7%20TensorRT-LLM%20%C2%B7%20MindIE%22%5D%0A%20%20Root%20--%3E%20Dir%5B%225%20%E5%A4%A7%E4%BC%98%E5%8C%96%E6%96%B9%E5%90%91%3Cbr%2F%3EHost%20%E5%BC%80%E9%94%80%20%C2%B7%20%E8%B4%9F%E8%BD%BD%E5%9D%87%E8%A1%A1%20%C2%B7%20%E9%80%9A%E4%BF%A1%20%C2%B7%20%E9%87%8F%E5%8C%96%20%C2%B7%20%E7%AE%97%E5%AD%90%E8%9E%8D%E5%90%88%22%5D%0A%20%20Root%20--%3E%20Tech%5B%22%E5%85%B3%E9%94%AE%E6%8A%80%E6%9C%AF%3Cbr%2F%3EKV%20Cache%20%C2%B7%20%E6%89%B9%E5%A4%84%E7%90%86%20%C2%B7%20%E6%8A%95%E6%9C%BA%E8%A7%A3%E7%A0%81%20%C2%B7%20PD%20%E5%88%86%E7%A6%BB%22%5D%0A%20%20Root%20--%3E%20Layer%5B%22%E4%B8%89%E5%B1%82%E8%90%BD%E5%9C%B0%3Cbr%2F%3E%E7%AE%97%E5%AD%90%E5%B1%82%20%C2%B7%20%E6%A8%A1%E5%9E%8B%E5%B1%82%20%C2%B7%20%E7%B3%BB%E7%BB%9F%E5%B1%82%22%5D%0A%20%20Layer%20--%3E%20Metric%5B%22%E6%80%A7%E8%83%BD%E6%8C%87%E6%A0%87%3Cbr%2F%3ETTFT%20%C2%B7%20TPOT%20%C2%B7%20Throughput%20%C2%B7%20SLO%22%5D%0A`})]),fallback:t(()=>[...d[0]||=[o(` Loading... `,-1)]]),_:1})),d[4]||=s(`<h2 id="_1-推理引擎与服务框架" tabindex="-1">1. 推理引擎与服务框架 <a class="header-anchor" href="#_1-推理引擎与服务框架" aria-label="Permalink to “1. 推理引擎与服务框架”">​</a></h2><p>生产环境通常基于开源推理引擎构建，而非从零写 kernel。主流选择：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>引擎</th><th>定位</th><th>代表特性</th><th>深入阅读</th></tr></thead><tbody><tr><td><strong>vLLM</strong></td><td>高吞吐、内存高效的开源推理引擎</td><td>PagedAttention、Continuous Batching、Automatic Prefix Caching、异步调度器（V1）、内置量化与投机解码</td><td><a href="/llmtechsite/inference/inference-engine/vllm/architecture">vLLM 架构设计</a></td></tr><tr><td><strong>SGLang</strong></td><td>面向复杂推理与多模态的高性能框架</td><td>RadixAttention（前缀树缓存）、分层缓存（HiCache）、PD 分离、结构化输出</td><td><a href="/llmtechsite/inference/inference-engine/sglang/introduction">SGLang 介绍</a></td></tr><tr><td><strong>TensorRT-LLM</strong></td><td>NVIDIA 官方优化推理引擎</td><td>In-flight Batching、深度图优化、FP8/INT4 内核、TP/PP/EP 多级并行</td><td>—</td></tr><tr><td><strong>MindIE</strong></td><td>华为昇腾推理引擎（MindIE-Service 服务化 / MindIE-Turbo 加速库）</td><td>昇腾 NPU 图编译、量化工具、服务化部署</td><td><a href="/llmtechsite/ascend/ecosystem/gpu-ascend-llm-ecosystem-research">GPU vs 昇腾全景对比</a></td></tr><tr><td><strong>DeepSpeed-Inference / FlashInfer</strong></td><td>算子/内核级库</td><td>高性能 attention 与 GEMM 内核、稀疏模板</td><td>—</td></tr></tbody></table></div><h2 id="_2-优化方向总览" tabindex="-1">2. 优化方向总览 <a class="header-anchor" href="#_2-优化方向总览" aria-label="Permalink to “2. 优化方向总览”">​</a></h2><p>推理优化可归纳为 <strong>5 个方向</strong>：</p><ol><li><strong>降低 Host 开销</strong>：CUDA Graph 使能、异步调度、异步 KV 传输、PP 并行</li><li><strong>避免快慢卡（负载不均）</strong>：DPLB（数据并行负载均衡）、EPLB（专家并行负载均衡）、动态 CP</li><li><strong>降低通信占比</strong>：掩盖（DBO、共享专家多流）、效率（分层通信）、通信量（量化通信、关闭 TP）</li><li><strong>低精度量化</strong>：W8A8、W4A8、小模型训练优化、SP / DSA-CP</li><li><strong>算子融合</strong>：MegaMoE、Triton Reject Sampler、访存优化（权重预取、KV Cache 量化）、显存优化（投机解码、WeightShard、SURESH、去冗余计算）</li></ol><h2 id="_3-关键技术一览" tabindex="-1">3. 关键技术一览 <a class="header-anchor" href="#_3-关键技术一览" aria-label="Permalink to “3. 关键技术一览”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>技术</th><th>一句话定位</th><th>深入阅读</th></tr></thead><tbody><tr><td><strong>KV Cache</strong></td><td>缓存历史 K/V，避免重复计算自回归前序</td><td><a href="/llmtechsite/inference/inference-optimization/kv-cache">KV Cache 机制详解</a></td></tr><tr><td><strong>PagedAttention</strong></td><td>显存分页管理（OS 虚拟分页思想），消除 KV 碎片与浪费</td><td><a href="/llmtechsite/inference/inference-engine/vllm/paged-attention">PagedAttention</a></td></tr><tr><td><strong>Continuous Batching</strong></td><td>请求级动态调度，迭代级回收空闲槽位，消除批间等待</td><td><a href="/llmtechsite/inference/inference-optimization/continuous-batching">连续批处理</a></td></tr><tr><td><strong>Chunked Prefill</strong></td><td>长请求分块预填充，与解码交错，避免阻塞与长尾延迟</td><td><a href="/llmtechsite/inference/inference-optimization/chunked-prefill">Chunked Prefill</a></td></tr><tr><td><strong>Prefix Caching</strong></td><td>前缀树/哈希复用共享前缀 KV，命中即省预填充</td><td><a href="/llmtechsite/inference/inference-engine/vllm/prefix-caching">Prefix Caching</a></td></tr><tr><td><strong>Constrained Decoding</strong></td><td>约束解码（文法/正则/JSON Schema），保证输出格式</td><td>—</td></tr><tr><td><strong>Speculative Decoding</strong></td><td>草稿模型多 token 并行 + 大模型校验，突破串行瓶颈</td><td><a href="/llmtechsite/inference/inference-optimization/speculative-decoding">推测解码完全指南</a></td></tr><tr><td><strong>KV Cache 压缩</strong></td><td>量化 / 剪枝淘汰 / 检索式 / 稀疏，压缩缓存体积</td><td><a href="/llmtechsite/inference/inference-optimization/kv-cache-connector">KV Cache 管理与优化架构</a></td></tr><tr><td><strong>Prefill-Decode 分离</strong></td><td>两阶段分离部署，解耦算力需求，消除互相干扰</td><td><a href="/llmtechsite/inference/inference-optimization/pd-disaggregation">Prefill-Decode 分离</a></td></tr><tr><td><strong>FlashInfer</strong></td><td>高性能推理算子库，统一 attention kernel 调度与稀疏模板</td><td>—</td></tr></tbody></table></div><h2 id="_4-分层要点" tabindex="-1">4. 分层要点 <a class="header-anchor" href="#_4-分层要点" aria-label="Permalink to “4. 分层要点”">​</a></h2><p>从底层内核到上层服务，优化分别在三个层次展开：算子层（怎么算）、模型层（算什么东西）、系统层（怎么调度）。上层依赖下层，下层为上层提供算力底座。</p>`,10),(e(),u(i,null,{default:t(()=>[r(g,{id:`mermaid-274`,class:`mermaid`,graph:`graph%20TB%0A%20%20Serv%5B%22%E6%8E%A8%E7%90%86%E5%BC%95%E6%93%8E%3Cbr%2F%3EvLLM%20%C2%B7%20SGLang%20%C2%B7%20TensorRT-LLM%20%C2%B7%20MindIE%22%5D%20--%3E%20Sys%5B%22%E7%B3%BB%E7%BB%9F%E5%B1%82%3Cbr%2F%3E%E5%B9%B6%E8%A1%8C%20%C2%B7%20%E8%B0%83%E5%BA%A6%20%C2%B7%20PD%20%E5%88%86%E7%A6%BB%20%C2%B7%20%E6%8A%95%E6%9C%BA%E8%A7%A3%E7%A0%81%22%5D%0A%20%20Sys%20--%3E%20Mod%5B%22%E6%A8%A1%E5%9E%8B%E5%B1%82%3Cbr%2F%3E%E9%87%8F%E5%8C%96%20%C2%B7%20KV%20Cache%20%E5%8E%8B%E7%BC%A9%20%C2%B7%20MoE%22%5D%0A%20%20Mod%20--%3E%20Op%5B%22%E7%AE%97%E5%AD%90%E5%B1%82%3Cbr%2F%3EFlashAttention%20%C2%B7%20FlashInfer%20%C2%B7%20CUDA%20Graph%22%5D%0A`})]),fallback:t(()=>[...d[1]||=[o(` Loading... `,-1)]]),_:1})),d[5]||=s(`<h3 id="_4-1-算子层" tabindex="-1">4.1 算子层 <a class="header-anchor" href="#_4-1-算子层" aria-label="Permalink to “4.1 算子层”">​</a></h3><ul><li><strong>模型算子</strong>：Embedding、Linear、Matmul、RoPE、MHA/GQA/MQA、RMSNorm、Add、Softmax、MLP、MoE</li><li><strong>前后处理算子</strong>：Argmax、Top-K、Top-P、Temperature</li><li><strong>Attention 优化</strong>：FlashAttention V1–V4（V4 面向 Blackwell、支持 FP8/NVFP4）· FlashInfer · RingAttention · PagedAttention · MLA（<a href="/llmtechsite/inference/kernel-optimization/flash-attention">FlashAttention 详解</a>、<a href="/llmtechsite/llm/pretraining/multi-head-latent-attention">MLA</a>）</li><li><strong>算子加速</strong>：FlashMLA（DeepSeek 算子库）· GEMM 优化 · Fused MoE · DeepGEMM</li><li><strong>编译优化</strong>：torch.compile · CUDA Graph · Triton · MegaMoE（CUDA Graph 一次捕获、多次回放，显著降低 Host 启动开销）</li></ul><h3 id="_4-2-模型层" tabindex="-1">4.2 模型层 <a class="header-anchor" href="#_4-2-模型层" aria-label="Permalink to “4.2 模型层”">​</a></h3><ul><li><strong>算子融合</strong>：Add + RMSNorm 融合 · 计算与读写显存融合 · Fused MoE / FlashMLA</li><li><strong>推理特点</strong>：自回归 · KV Cache · Packing（长度分组填充）</li><li><strong>模型量化</strong>：Weight-only（GPTQ、AWQ）· Weight-Activation（SmoothQuant、W8A8、FP8）；W4A8 精度损失显著，W8A8 为生产甜点</li><li><strong>KV Cache 量化</strong>：FP8 / INT4 / NVFP4，与权重量化互补，进一步省显存</li><li><strong>MoE 优化</strong>：专家并行（EP）· 专家负载均衡（EPLB）· 共享专家多流 · 去冗余计算（<a href="/llmtechsite/llm/pretraining/mixture-of-experts">MoE 图解指南</a>）</li><li><strong>模型通信</strong>：AllReduce / AllGather / All2All · Tree / Ring AllReduce</li></ul><h3 id="_4-3-系统层" tabindex="-1">4.3 系统层 <a class="header-anchor" href="#_4-3-系统层" aria-label="Permalink to “4.3 系统层”">​</a></h3><ul><li><strong>并行策略</strong>：DP（数据）· TP（张量）· PP（流水线）· EP（专家）· CP（上下文/序列）→ <a href="/llmtechsite/distributed/overview/parallelism-overview">训练技术概论</a></li><li><strong>调度与批处理</strong>：Continuous Batching · Chunked Prefill · SLO 感知 · Prefix Caching · 优先级 / 公平 / 长度感知</li><li><strong>KV Cache 分级</strong>：L1-GPU / L2-CPU / L3-Remote · Paged KV / RadixAttention · Offload / 预取 / 淘汰</li><li><strong>投机解码</strong>：EAGLE V1–V3（基于特征图草稿）· MTP（多 token 预测）· Medusa（多 head 草稿）· DFlash · DSpark · 自投机 / N-gram</li><li><strong>PD 分离</strong>：DistServe · Mooncake（KVCache-centric）· TaiChi · HiCache（<a href="/llmtechsite/inference/inference-optimization/pd-disaggregation">Prefill-Decode 分离</a>）</li><li><strong>稳定性保障</strong>：Daily Test / 性能基线 · Metrics / Logs / Trace · 降级 / 故障诊断 / 流量回放</li></ul><h2 id="_5-关键性能指标" tabindex="-1">5. 关键性能指标 <a class="header-anchor" href="#_5-关键性能指标" aria-label="Permalink to “5. 关键性能指标”">​</a></h2><p>衡量推理服务质量的核心指标（<a href="/llmtechsite/inference/foundations/inference-metrics">推理指标</a>）：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>优化目标</th></tr></thead><tbody><tr><td><strong>TTFT</strong></td><td>首 token 延迟（从请求到首个输出 token）</td><td>越低越好（受 Prefill 影响）</td></tr><tr><td><strong>TPOT / ITL</strong></td><td>每 token 输出延迟 / token 间延迟</td><td>越低越好（受 Decode 影响）</td></tr><tr><td><strong>Throughput</strong></td><td>单位时间完成的请求/token 数</td><td>越高越好</td></tr><tr><td><strong>Context Length</strong></td><td>可处理的最大序列长度</td><td>KV Cache 与显存共同决定</td></tr><tr><td><strong>SLO 达标率</strong></td><td>延迟/吞吐目标（SLO）下的请求达标比例</td><td>越高越好（受调度器影响）</td></tr></tbody></table></div><h2 id="_6-新兴趋势" tabindex="-1">6. 新兴趋势 <a class="header-anchor" href="#_6-新兴趋势" aria-label="Permalink to “6. 新兴趋势”">​</a></h2><ul><li><strong>长上下文推理</strong>：KV Cache 分级与压缩、稀疏注意力（MiniMax Sparse Attention）、视觉-文本压缩，支撑百万级上下文</li><li><strong>多模态推理</strong>：视觉 token 压缩、跨模态注意力，降低视觉输入显存占用</li><li><strong>MoE 大规模部署</strong>：宽专家并行（Wide EP）、专家负载均衡成为吞吐关键</li><li><strong>异构与国产生态</strong>：昇腾（MindIE、vLLM-Ascend）、国产 GPU 适配成为国内落地重点（<a href="/llmtechsite/inference/kernel-optimization/gpu-npu-architecture">GPU 与 NPU 硬件组成</a>）</li><li><strong>编译驱动优化</strong>：torch.compile + CUDA Graph 组合持续降低 Host 侧开销</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><strong>GPU 工作原理</strong>：<a href="https://www.zhihu.com/zvideo/1421421171497304064" target="_blank" rel="noreferrer">视频</a> · <a href="/llmtechsite/inference/kernel-optimization/gpu-npu-architecture">GPU 与 NPU 硬件组成</a> · <a href="/llmtechsite/inference/kernel-optimization/brrr-first-principles">性能第一性原理</a></li><li><strong>注意力基础</strong>：<a href="/llmtechsite/llm/pretraining/attention-mha-mqa-gqa">MHA、MQA 与 GQA</a> · <a href="/llmtechsite/llm/pretraining/multi-head-latent-attention">MLA</a> · <a href="/llmtechsite/inference/kernel-optimization/flash-attention">FlashAttention 详解</a></li><li><strong>调优与评测</strong>：<a href="/llmtechsite/inference/inference-engine/vllm/performance-tuning">vLLM 性能调优</a> · <a href="/llmtechsite/inference/inference-engine/sglang/performance-tuning">SGLang 性能调优</a> · <a href="/llmtechsite/inference/foundations/inference-metrics">推理指标</a> · <a href="/llmtechsite/inference/foundations/sampling-parameters">解码采样参数解析</a></li><li><strong>模型与生态</strong>：<a href="/llmtechsite/llm/pretraining/mixture-of-experts">MoE 图解指南</a> · <a href="/llmtechsite/rlhf/papers/deepseek-r1">DeepSeek-R1</a> · <a href="/llmtechsite/ascend/ecosystem/gpu-ascend-llm-ecosystem-research">GPU vs 昇腾全景对比</a> · <a href="/llmtechsite/ascend/performance/npu-fusion-attention">NPU 融合注意力算子</a></li></ul>`,13)])}var m=l(f,[[`render`,p]]);export{d as __pageData,m as default};